using Azure;
using Azure.Search.Documents;
using Azure.Search.Documents.Models;
using InsuranceIntelligence.Api.Azure;
using InsuranceIntelligence.Domain.Common;
using InsuranceIntelligence.Infrastructure.Configuration;

namespace InsuranceIntelligence.Api.Tests;

/// <summary>
/// Verifies the OData filter generated by AzureAiSearchKnowledgeIndexProvider.BuildSearchFilter
/// enforces tenant isolation and optional product-line scoping.
/// </summary>
public sealed class AzureAiSearchRetrievalProviderTests
{
    [Fact]
    public void BuildSearchFilter_IncludesTenantAndWorkspace()
    {
        var scope = TenantScope.Create("tenant-abc", "workspace-xyz");
        var filter = AzureAiSearchKnowledgeIndexProvider.BuildSearchFilter(scope, null);

        Assert.Contains("tenantId eq 'tenant-abc'", filter, StringComparison.Ordinal);
        Assert.Contains("workspaceId eq 'workspace-xyz'", filter, StringComparison.Ordinal);
    }

    [Fact]
    public void BuildSearchFilter_IncludesApprovalStatusAndIndexedStatus()
    {
        var scope = TenantScope.Create("t1", "w1");
        var filter = AzureAiSearchKnowledgeIndexProvider.BuildSearchFilter(scope, null);

        Assert.Contains("approvalStatus eq 'Approved'", filter, StringComparison.Ordinal);
        Assert.Contains("indexedStatus eq 'Indexed'", filter, StringComparison.Ordinal);
    }

    [Fact]
    public void BuildSearchFilter_AppendsProductLineWhenSupplied()
    {
        var scope = TenantScope.Create("t1", "w1");
        var filter = AzureAiSearchKnowledgeIndexProvider.BuildSearchFilter(scope, "Motor");

        Assert.Contains("productLine eq 'Motor'", filter, StringComparison.Ordinal);
    }

    [Fact]
    public void BuildSearchFilter_OmitsProductLineWhenNull()
    {
        var scope = TenantScope.Create("t1", "w1");
        var filter = AzureAiSearchKnowledgeIndexProvider.BuildSearchFilter(scope, null);

        Assert.DoesNotContain("productLine", filter, StringComparison.Ordinal);
    }

    [Fact]
    public void BuildSearchFilter_EscapesSingleQuotesInTenantId()
    {
        var scope = TenantScope.Create("tenant-o'clock", "workspace-1");
        var filter = AzureAiSearchKnowledgeIndexProvider.BuildSearchFilter(scope, null);

        // OData single-quote escaping: ' becomes ''
        Assert.Contains("tenantId eq 'tenant-o''clock'", filter, StringComparison.Ordinal);
    }
}
